    static void bul(String isbn) throws StokYokException {
        try {
            Integer.parseInt(isbn);
        } catch (NumberFormatException e) {
            throw new StokYokException(isbn, e);
        }
    }

    public static void main(String[] args) {
        try {
            bul("978X");
        } catch (StokYokException e) {
            System.out.println(e.getMessage());
            System.out.println(e.getIsbn());
            System.out.println(e.getCause().getClass().getSimpleName());
            Throwable t = e;
            System.out.println((t instanceof Exception) + " " + (t instanceof RuntimeException));
        }
        try {
            bul("978");
            System.out.println("bulundu");
        } catch (StokYokException e) {
            System.out.println("olmaz");
        }
    }
}

