import java.util.*;

public class EszamanliDegisiklik {
    public static void main(String[] args) {
        List<String> l = new ArrayList<>(List.of("a", "bb", "ccc", "dddd"));
        try {
            for (String s : l) if (s.length() == 2) l.remove(s);
        } catch (ConcurrentModificationException e) {
            System.out.println("CME yakalandi, liste = " + l);
        }
        List<String> l2 = new ArrayList<>(List.of("a", "bb", "ccc", "dddd"));
        Iterator<String> it = l2.iterator();
        while (it.hasNext()) if (it.next().length() % 2 == 0) it.remove();
        System.out.println(l2);

        List<String> l3 = new ArrayList<>(List.of("a", "bb", "ccc", "dddd"));
        l3.removeIf(s -> s.length() > 2);
        System.out.println(l3);

        Deque<Integer> yigin = new ArrayDeque<>();
        yigin.push(1); yigin.push(2); yigin.push(3);
        System.out.println(yigin.pop() + " " + yigin.peek() + " " + yigin.size());
    }
}

