import java.util.*;

public class SinirliTip {
    static <T extends Comparable<T>> T enBuyuk(List<T> l) {
        T m = l.get(0);
        for (T x : l) if (x.compareTo(m) > 0) m = x;
        return m;
    }
    static double toplam(List<? extends Number> l) {
        double t = 0;
        for (Number n : l) t += n.doubleValue();
        return t;
    }
    static void doldur(List<? super Integer> l) { for (int i = 1; i <= 3; i++) l.add(i); }

    public static void main(String[] args) {
        System.out.println(enBuyuk(List.of(3, 9, 4)));
        System.out.println(enBuyuk(List.of("elma", "armut", "kivi")));
        System.out.println(toplam(List.of(1, 2, 3)));
        System.out.println(toplam(List.of(1.5, 2.5)));
        List<Number> n = new ArrayList<>();
        doldur(n);
        System.out.println(n);
        List<Object> o = new ArrayList<>();
        doldur(o);
        System.out.println(o);
    }
}

import java.util.*;

public class PECS {
    static <T> void kopyala(List<? extends T> kaynak, List<? super T> hedef) {
        for (T t : kaynak) hedef.add(t);
    }

    public static void main(String[] args) {
        List<Integer> kaynak = List.of(1, 2, 3);
        List<Number> hedef = new ArrayList<>(List.of(0.5));
        kopyala(kaynak, hedef);
        System.out.println(hedef);

        List<? extends Number> okunur = kaynak;
        System.out.println(okunur.get(0).intValue() + okunur.size());

