public class SenkronizasyonVeKilit {
    private int bakiye = 100;

    synchronized void cek(int m) { if (bakiye >= m) bakiye -= m; }
    synchronized int bakiye() { return bakiye; }

    public static void main(String[] args) throws Exception {
        SenkronizasyonVeKilit h = new SenkronizasyonVeKilit();
        CountDownLatch kapi = new CountDownLatch(1);
        CountDownLatch bitti = new CountDownLatch(4);
        for (int i = 0; i < 4; i++) {
            new Thread(() -> {
                try { kapi.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                for (int j = 0; j < 10; j++) h.cek(2);
                bitti.countDown();
            }).start();
        }
        System.out.println("baslangic = " + h.bakiye());
        kapi.countDown();
        bitti.await();
        System.out.println("son = " + h.bakiye());
    }
}

