import java.util.*;

class Kutuphane13 {
    private final Map<String, Integer> stok = new HashMap<>();

    void ekle(String isbn, int adet) {
        if (adet <= 0) throw new IllegalArgumentException("adet pozitif olmali");
        stok.merge(isbn, adet, Integer::sum);
    }
    boolean oduncVer(String isbn) {
        int s = stok.getOrDefault(isbn, 0);
        if (s == 0) return false;
        stok.put(isbn, s - 1);
        return true;
    }
    int stok(String isbn) { return stok.getOrDefault(isbn, 0); }
}

public class KucukTestCercevesi {
    static int gecen = 0, kalan = 0;

    static void esitMi(Object beklenen, Object gercek, String ad) {
        if (Objects.equals(beklenen, gercek)) { gecen++; System.out.println("GECTI  " + ad); }
        else { kalan++; System.out.println("KALDI  " + ad + " beklenen=" + beklenen + " gercek=" + gercek); }
    }
    static void istisnaAtarMi(Class<? extends Throwable> tip, Runnable r, String ad) {
        try {
            r.run();
            kalan++;
            System.out.println("KALDI  " + ad + " (istisna atilmadi)");
        } catch (Throwable t) {
            if (tip.isInstance(t)) { gecen++; System.out.println("GECTI  " + ad); }
            else { kalan++; System.out.println("KALDI  " + ad + " yanlis tip: " + t.getClass().getSimpleName()); }
        }
    }

    public static void main(String[] args) {
        Kutuphane13 k = new Kutuphane13();
        k.ekle("978-1", 2);
        esitMi(2, k.stok("978-1"), "ekleme stogu artirir");
        esitMi(true, k.oduncVer("978-1"), "stok varken odunc verilir");
        esitMi(1, k.stok("978-1"), "odunc stogu azaltir");
        esitMi(false, k.oduncVer("978-9"), "olmayan kitap odunc verilemez");
        istisnaAtarMi(IllegalArgumentException.class, () -> k.ekle("978-1", 0), "adet 0 olamaz");
        esitMi(5, k.stok("978-1"), "bilerek yanlis beklenti");
        System.out.println("gecen=" + gecen + " kalan=" + kalan);
    }
}

