class BellekDepo<T extends Kimlikli> {
    private final Map<String, T> veri = new LinkedHashMap<>();
    boolean kaydet(T t) { return veri.put(t.id(), t) == null; }
    Optional<T> bul(String id) { return Optional.ofNullable(veri.get(id)); }
    List<T> filtrele(Predicate<T> p) { return veri.values().stream().filter(p).toList(); }
    int adet() { return veri.size(); }
    boolean sil(String id) { return veri.remove(id) != null; }
}

