    }
}

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

class GecikmeHesabi {
    static final int SERBEST_GUN = 15;
    static final double GUNLUK_CEZA = 0.50;

    static double ceza(LocalDate alis, LocalDate iade) {
        if (iade.isBefore(alis)) throw new IllegalArgumentException("iade alis tarihinden once olamaz");
        long gun = ChronoUnit.DAYS.between(alis, iade);
        long gecikme = Math.max(0, gun - SERBEST_GUN);
        return gecikme * GUNLUK_CEZA;
    }
}

public class ServisKurallari {
    public static void main(String[] args) {
        LocalDate a = LocalDate.of(2025, 3, 1);
        System.out.println(GecikmeHesabi.ceza(a, LocalDate.of(2025, 3, 10)));
        System.out.println(GecikmeHesabi.ceza(a, LocalDate.of(2025, 3, 16)));
        System.out.println(GecikmeHesabi.ceza(a, LocalDate.of(2025, 3, 21)));
        System.out.println(GecikmeHesabi.ceza(a, a));
        try {
            GecikmeHesabi.ceza(a, LocalDate.of(2025, 2, 28));
        } catch (IllegalArgumentException e) {
            System.out.println("hata: " + e.getMessage());
        }
        System.out.println(ChronoUnit.DAYS.between(a, LocalDate.of(2025, 4, 1)));
    }
}

