public class RaporKatmani {
    public static void main(String[] args) {
        List<Odunc14> kayitlar = List.of(
                new Odunc14("ayse", "978-1", 20),
                new Odunc14("ayse", "978-2", 10),
                new Odunc14("mehmet", "978-1", 30),
                new Odunc14("zeynep", "978-3", 5));

        Map<String, Long> adet = kayitlar.stream()
                .collect(Collectors.groupingBy(Odunc14::uye, TreeMap::new, Collectors.counting()));
        System.out.println(adet);

        Map<String, Integer> toplamGun = kayitlar.stream()
                .collect(Collectors.groupingBy(Odunc14::uye, TreeMap::new, Collectors.summingInt(Odunc14::gun)));
        System.out.println(toplamGun);

        System.out.println(kayitlar.stream().filter(o -> o.gun() > 15).map(Odunc14::uye).sorted().toList());
        System.out.println(kayitlar.stream().mapToInt(Odunc14::gun).average().orElse(0));
        System.out.println(kayitlar.stream().max(Comparator.comparingInt(Odunc14::gun)).map(Odunc14::uye).orElse("-"));
    }
}

